      "explanation": "Kolanjitte enfekte safra yolu basıncı düşürülmeden sepsis kontrol altına alınamayabilir. ERCP taş çıkarma, sfinkterotomi veya stent ile hem tanısal hem terapötik biliyer drenaj sağlar.",
