// V240 — Structured back-face rewrite guard for all 1000 Hap Bilgi cards.
// Each back-face field must carry a different educational job:
// answer = direct response, explanation = why, tusTip = exam catching clue,
// differentialNote = explicit comparison/trap distinction.
function sentenceKeyForPearl(value = '') {
  return cleanText(value)
    .toLocaleLowerCase('tr')
    .replace(/[“”"'’`´]/g, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function splitPearlSentences(value = '') {
  return cleanText(value)
    .split(/(?<=[.!?])\s+/u)
    .map((item) => cleanText(item))
    .filter(Boolean);
}

function hasRepeatedPearlSentence(a = '', b = '') {
  const aKeys = new Set(splitPearlSentences(a).map(sentenceKeyForPearl).filter((item) => item.length > 8));
  if (!aKeys.size) return false;
  return splitPearlSentences(b).some((sentence) => aKeys.has(sentenceKeyForPearl(sentence)));
}

function removePearlSentencesAlreadyUsed(value = '', usedTexts = []) {
  const used = new Set(usedTexts.flatMap((text) => splitPearlSentences(text).map(sentenceKeyForPearl)).filter((item) => item.length > 8));
  const kept = splitPearlSentences(value).filter((sentence) => !used.has(sentenceKeyForPearl(sentence)));
  return cleanSentence(kept.join(' '));
}

function answerWithoutFinalPunctuation(value = '') {
  return trimSentenceEnd(value)
    .replace(/^(Yanıt|Cevap)\s*:?\s*/iu, '')
    .trim();
}

function pearlCuePhrase(card = {}, limit = 3) {
  const cues = keywordItems(card.keywords || []).slice(0, limit);
  return joinTurkishList(cues);
}

function roleSpecificTusTip(card = {}) {
  const cues = pearlCuePhrase(card, 3);
  const topicName = displayTopicForFront(cleanText(card.topic || 'bu başlık'))
    .replace(/^Anafilaksi antihistaminik$/iu, 'Anafilaksi tedavisi')
    .replace(/^Hiperkalemi tedavi sırası$/iu, 'Hiperkalemi tedavisi');
  const answer = answerWithoutFinalPunctuation(card.answer || card.back || topicName);
  const type = cleanText(card.cardType || '');
  const trapSource = `${card.answer || ''} ${card.explanation || ''} ${card.differentialNote || ''}`.toLocaleLowerCase('tr');
  const dimension = textHasAny(trapSource, [/adrenalin/u, /antihistaminik/u, /steroid/u, /insülin/u, /kalsiyum/u, /antibiyotik/u, /tedavi/u, /ilk basamak/u])
    ? 'tedavi önceliği'
    : inferTrapQuestionDimension(trapSource, card);

  if (/Ayırıcı nokta/iu.test(type)) {
    return cleanSentence(cues
      ? `${topicName} için çeldirici ${dimension} üzerinden kurulur; ${cues} birlikte okunarak ayrım yapılır`
      : `${topicName} için çeldirici ${dimension} üzerinden kurulur; karar tek bir bulguya değil klinik bağlama göre verilir`);
  }

  if (/Anahtar patern/iu.test(type)) {
    return cleanSentence(cues
      ? `${cues} yan yana geldiğinde patern ${answer} ekseninde yorumlanır; tek başına izole bir bulgu yeterli kabul edilmez`
      : `${topicName} için yüksek verimli nokta, yanıtı izole ezberden değil patern bütünlüğünden çıkarmaktır`);
  }

  if (/Kısa uygulama/iu.test(type)) {
    return cleanSentence(cues
      ? `${topicName} kısa uygulama kartlarında ${cues} paternini tamamlayan bulgu, yapı veya mekanizma sorgulanır`
      : `${topicName} için kısa uygulama kartında yanıt, kavramın klinik karşılığını doğrudan tanımaya dayanır`);
  }

  return cleanSentence(cues
    ? `${cues} birlikte görüldüğünde öncelikli ilişki ${answer} yönündedir`
    : `${topicName} için yakalatıcı nokta, cevabı genel tanımdan değil ayırt ettirici ipucundan tanımaktır`);
}

function fallbackDifferentialNote(card = {}) {
  const id = String(card.id || '');
  if (id === 'tus-pearl-tus-spot-olgular-163-trap') {
    return 'Kalsiyum potasyumu düşürmez, kardiyak membranı stabilize eder; insülin-glukoz ise potasyumu hücre içine kaydıran sonraki basamaktır.';
  }
  if (id === 'tus-pearl-tus-spot-olgular-164-trap') {
    return 'Antihistaminik ürtiker ve kaşıntıyı hafifletir; bronkospazm, laringeal ödem veya hipotansiyonda adrenalinin yerine geçmez.';
  }
  if (id === 'tus-pearl-medical-pharmacology-166-trap') {
    return 'Opioid toksidromunda miyozis ve solunum depresyonu beklenir; salisilat erken dönemde solunum merkezini uyararak hiperventilasyon yapar.';
  }

  const cues = pearlCuePhrase(card, 2);
  const topicName = cleanText(card.topic || 'bu kavram');
  const dimension = inferTrapQuestionDimension(`${card.answer || ''} ${card.explanation || ''}`, card);
  return cleanSentence(cues
    ? `${topicName} benzerlerinden özellikle ${dimension} ve ${cues} birlikteliğiyle ayrılır`
    : `${topicName} benzer kavramlardan ayırıcı klinik bağlam ve mekanizma düzeyiyle ayrılır`);
}


function polishPearlBackRoleText(value = '') {
  return cleanSentence(value)
    .replace(/\s+ile\s+daha\s+çok\s+sorulur\.?$/giu, ' ile ilişkilidir.')
    .replace(/\s+ile\s+daha\s+çok\s+sorulur/giu, ' ile ilişkilidir')
    .replace(/\s+daha\s+çok\s+sorulur\.?$/giu, ' ile ilişkilidir.')
    .replace(/\s+daha\s+çok\s+sorulur/giu, ' ile ilişkilidir')
    .replace(/\bile\s+karışır\b/giu, 'ile karıştırılabilir')
    .replace(/\bkarışır\b/giu, 'karıştırılabilir')
    .replace(/\s+/g, ' ')
    .trim();
}

function revisePearlBackFaceFields(card = {}) {
  const answer = cleanSentence(answerWithoutFinalPunctuation(card.answer || card.back));
  let explanation = cleanSentence(stripTusBoilerplate(card.explanation || ''));
  if (!explanation || hasRepeatedPearlSentence(explanation, answer)) {
    explanation = cleanSentence(stripTusBoilerplate(card.explanation || card.back || card.topic || ''));
  }

  const originalDifferential = cleanSentence(card.differentialNote || '');
  let differentialNote = originalDifferential;
  if (!differentialNote || hasRepeatedPearlSentence(differentialNote, answer) || hasRepeatedPearlSentence(differentialNote, explanation)) {
    differentialNote = fallbackDifferentialNote(card);
  }

  let tusTip = cleanSentence(card.tusTip || '');
  const tipRepeatsOtherField = !tusTip
    || hasRepeatedPearlSentence(tusTip, answer)
    || hasRepeatedPearlSentence(tusTip, explanation)
    || hasRepeatedPearlSentence(tusTip, differentialNote);
  if (tipRepeatsOtherField || !/Anahtar patern/iu.test(card.cardType || '')) {
    tusTip = roleSpecificTusTip({ ...card, answer, explanation, differentialNote });
  }
  tusTip = removePearlSentencesAlreadyUsed(tusTip, [answer, explanation, differentialNote]) || roleSpecificTusTip({ ...card, answer, explanation, differentialNote });
  differentialNote = removePearlSentencesAlreadyUsed(differentialNote, [answer, explanation, tusTip]) || fallbackDifferentialNote({ ...card, answer, explanation, tusTip });

  const polishedAnswer = polishPearlBackRoleText(answer);
  const polishedExplanation = polishPearlBackRoleText(explanation);
  const polishedTusTip = polishPearlBackRoleText(tusTip);
  const polishedDifferentialNote = polishPearlBackRoleText(differentialNote);

  return {
    ...card,
    back: polishedAnswer,
    answer: polishedAnswer,
    explanation: polishedExplanation,
    tusTip: polishedTusTip,
    differentialNote: polishedDifferentialNote,
    noteLabel: card.noteLabel || 'Ayırıcı not',
  };
}

function applyFinalTextOverride(card = {}, override = {}) {
  if (!override) return card;
  const nextCard = { ...card };

  if (Object.prototype.hasOwnProperty.call(override, 'front')) {
    nextCard.front = cleanQuestion(override.front || card.front);
  }
  if (Object.prototype.hasOwnProperty.call(override, 'topic')) {
    nextCard.topic = cleanText(override.topic || card.topic);
  }
  if (Array.isArray(override.keywords)) {
    nextCard.keywords = override.keywords.map((keyword) => cleanText(keyword)).filter(Boolean);
  }

  ['back', 'answer', 'explanation', 'tusTip', 'differentialNote'].forEach((field) => {
    if (Object.prototype.hasOwnProperty.call(override, field)) {
      nextCard[field] = cleanSentence(override[field] || '');
    }
  });

  return nextCard;
}

function applyRevisedPearlCardText(card = {}) {
  const baseOverride = TUS_PEARL_REVISED_TEXT_OVERRIDES[card.id] || null;
  const anatomyOverride = TUS_PEARL_ANATOMY_FIRST56_TEXT_OVERRIDES[card.id] || null;
  const physiologyOverride = TUS_PEARL_PHYSIOLOGY_FIRST47_TEXT_OVERRIDES[card.id] || null;
  const histologyEmbryologyOverride = TUS_PEARL_HISTOLOGY_EMBRYOLOGY_FIRST34_TEXT_OVERRIDES[card.id] || null;
  const medicalBiochemistryOverride = TUS_PEARL_MEDICAL_BIOCHEMISTRY_FIRST74_TEXT_OVERRIDES[card.id] || null;
  const medicalMicrobiologyOverride = TUS_PEARL_MEDICAL_MICROBIOLOGY_FIRST52_TEXT_OVERRIDES[card.id] || null;
  const medicalMicrobiologySecond52Override = TUS_PEARL_MEDICAL_MICROBIOLOGY_SECOND52_TEXT_OVERRIDES[card.id] || null;
  const medicalPathologyFirst84Override = TUS_PEARL_MEDICAL_PATHOLOGY_FIRST84_TEXT_OVERRIDES[card.id] || null;
  const medicalPharmacologyFirst51Override = TUS_PEARL_MEDICAL_PHARMACOLOGY_FIRST51_TEXT_OVERRIDES[card.id] || null;
  const medicalPharmacologySecond50Override = TUS_PEARL_MEDICAL_PHARMACOLOGY_SECOND50_TEXT_OVERRIDES[card.id] || null;
  const internalMedicineFirst50Override = TUS_PEARL_INTERNAL_MEDICINE_FIRST50_TEXT_OVERRIDES[card.id] || null;
  const internalMedicineSecond50Override = TUS_PEARL_INTERNAL_MEDICINE_SECOND50_TEXT_OVERRIDES[card.id] || null;
  const internalMedicineThird59Override = TUS_PEARL_INTERNAL_MEDICINE_THIRD59_TEXT_OVERRIDES[card.id] || null;
  const pediatricsFirst63Override = TUS_PEARL_PEDIATRICS_FIRST63_TEXT_OVERRIDES[card.id] || null;
  const pediatricsSecond63Override = TUS_PEARL_PEDIATRICS_SECOND63_TEXT_OVERRIDES[card.id] || null;
  const obgynFirst64Override = TUS_PEARL_OBGYN_FIRST64_TEXT_OVERRIDES[card.id] || null;
  const smallClerkshipsFirst58Override = TUS_PEARL_SMALL_CLERKSHIPS_FIRST58_TEXT_OVERRIDES[card.id] || null;
  const override = baseOverride || anatomyOverride || physiologyOverride || histologyEmbryologyOverride || medicalBiochemistryOverride || medicalMicrobiologyOverride || medicalMicrobiologySecond52Override || medicalPathologyFirst84Override || medicalPharmacologyFirst51Override || medicalPharmacologySecond50Override || internalMedicineFirst50Override || internalMedicineSecond50Override || internalMedicineThird59Override || pediatricsFirst63Override || pediatricsSecond63Override || obgynFirst64Override || smallClerkshipsFirst58Override
    ? { ...(baseOverride || {}), ...(anatomyOverride || {}), ...(physiologyOverride || {}), ...(histologyEmbryologyOverride || {}), ...(medicalBiochemistryOverride || {}), ...(medicalMicrobiologyOverride || {}), ...(medicalMicrobiologySecond52Override || {}), ...(medicalPathologyFirst84Override || {}), ...(medicalPharmacologyFirst51Override || {}), ...(medicalPharmacologySecond50Override || {}), ...(internalMedicineFirst50Override || {}), ...(internalMedicineSecond50Override || {}), ...(internalMedicineThird59Override || {}), ...(pediatricsFirst63Override || {}), ...(pediatricsSecond63Override || {}), ...(obgynFirst64Override || {}), ...(smallClerkshipsFirst58Override || {}) }
    : null;
  const preRevisedCard = override ? applyFinalTextOverride(card, {
    front: override.front,
    keywords: override.keywords,
  }) : card;

  const revisedCard = revisePearlBackFaceFields(preRevisedCard);
  return override ? applyFinalTextOverride(revisedCard, override) : revisedCard;
}

export function buildTusPearlCards() {
  return TUS_PEARL_TOPICS.flatMap((topic, topicIndex) => VARIANT_LABELS.map((_, variantIndex) => buildCard(topic, topicIndex, variantIndex)))
    .filter((card) => isPearlCardQualityApproved(card))
    .map(applyRevisedPearlCardText);
}

export const TUS_PEARL_CARDS = buildTusPearlCards();

export const TUS_PEARL_CARD_STATS = Object.freeze({
  total: TUS_PEARL_CARDS.length,
  pastQuestionCount: TUS_PEARL_CARDS.filter((card) => card.appearedYears?.length || card.isPastQuestionDerived).length,
  byBranch: TUS_PEARL_CARDS.reduce((acc, card) => {
    acc[card.branchId] = (acc[card.branchId] || 0) + 1;
    return acc;
  }, {}),
});
